EditorDocument Doc()=>new(){OriginalWidth=1000,OriginalHeight=800,SourceHash="source"};
AnnotationBox Bounds(Annotation a)=>ObjectControl.RotatedBounds(new(a.Left,a.Top,a.Width,a.Height),a.Rotation);
