 var a=new Annotation{Kind=kind,RegionShape=shape,X1=100,Y1=120,X2=300,Y2=240,Magnification=3.5,FocusOpacity=68,Rotation=31,Color="#123456",EffectSize=40};var d=Doc();d.Annotations.Add(a);d.Validate(1000,800,"source");var reopened=EditorDocument.Deserialize(d.Serialize());reopened.Validate(1000,800,"source");Check(d.Serialize()==reopened.Serialize(),"Roundtrip effect and geometry: "+kind+"/"+shape);
 Check(JsonSerializer.Serialize(a.Copy(),EditorDocument.JsonOptions)==JsonSerializer.Serialize(a,EditorDocument.JsonOptions),"Clone retains all focus settings: "+kind+"/"+shape);
}
foreach(var version in Enumerable.Range(1,8)){var d=Doc();d.Version=version;var a=new Annotation{Kind=AnnotationKind.Highlight,X1=1,Y1=2,X2=30,Y2=40,Color="#ABCDE0"};d.Annotations.Add(a);d.Validate(1000,800,"source");Check(d.Version==12&&a.RegionShape==RegionShape.Rectangle&&Math.Abs(a.FocusOpacity*255/100-78)<1e-8,"Legacy highlight keeps rectangular geometry and alpha 78: "+version);}
