var lens=new Annotation{Kind=AnnotationKind.Magnifier,X1=100,Y1=100,X2=300,Y2=260,Magnification=2};var sample=FocusStudio.LensSample(lens);Check(sample==new AnnotationBox(150,140,100,80),"Lens maps source center to a smaller sampling region without resizing the file");lens.Translate(50,30);var moved=FocusStudio.LensSample(lens);Check(moved.X==sample.X+50&&moved.Y==sample.Y+30,"Lens sampling follows its position");
var transformed=lens.Copy();AnnotationEditing.Transform(transformed,lens,new(lens.Left,lens.Top,lens.Width,lens.Height),new(10,20,400,320));Check(transformed.Width==400&&transformed.Height==320&&transformed.Magnification==2,"Resize changes lens footprint and preserves zoom factor");
var d2=Doc();lens.RegionShape=RegionShape.Ellipse;d2.Annotations.Add(lens);var duplicate=AnnotationEditing.Duplicate(d2,[lens.Id],Bounds);Check(duplicate.Count==1&&d2.Annotations[^1].Magnification==2&&d2.Annotations[^1].RegionShape==RegionShape.Ellipse,"Duplicate retains editable lens settings");
var clipboard=AnnotationClipboard.Copy(d2,[lens.Id]);var target=Doc();AnnotationClipboard.Paste(target,clipboard,16,Bounds);Check(target.Annotations[0].Id!=lens.Id&&target.Annotations[0].Magnification==2&&target.Annotations[0].RegionShape==RegionShape.Ellipse,"Clipboard preserves effect shape and zoom with independent identity");
var session=new EditorSession(d2);session.Change(d=>{d.Annotations[0].Magnification=5;d.Annotations[0].RegionShape=RegionShape.Rectangle;});session.Undo();Check(session.Document.Annotations[0].Magnification==2&&session.Document.Annotations[0].RegionShape==RegionShape.Ellipse,"Undo restores lens configuration");session.Redo();Check(session.Document.Annotations[0].Magnification==5,"Redo restores changed zoom factor");
lens.StrokeEnabled=false;lens.StrokeOpacity=25;lens.Dash=StrokePattern.Dash;var preset=AnnotationPreset.From("Kính riêng",lens);preset.Validate();var presetCopy=JsonSerializer.Deserialize<AnnotationPreset>(JsonSerializer.Serialize(preset,EditorDocument.JsonOptions),EditorDocument.JsonOptions)!;var dest=new Annotation{Kind=AnnotationKind.Magnifier};presetCopy.Apply(dest);Check(dest.RegionShape==lens.RegionShape&&dest.Magnification==lens.Magnification&&!dest.StrokeEnabled&&dest.StrokeOpacity==25&&dest.Dash==StrokePattern.Dash,"Focus preset persists and applies settings");Reject(()=>new FocusPreset(RegionShape.Rectangle,2,70,AnnotationKind.Text).Validate(),"Preset cannot select an unrelated tool");
var layers=Doc();var solid=new Annotation{Kind=AnnotationKind.Cover,X1=10,Y1=10,X2=50,Y2=50};var blur=new Annotation{Kind=AnnotationKind.Blur};var spot=new Annotation{Kind=AnnotationKind.Spotlight};var normal=new Annotation{Kind=AnnotationKind.Rectangle};layers.Annotations.AddRange([solid,normal,spot,blur]);AnnotationEditing.Reorder(layers,[spot.Id],AnnotationOrder.Front);Check(layers.Annotations[0].Id==spot.Id&&layers.Annotations[^1].Id==solid.Id,"Spotlight shade stays beneath annotations and solid masks stay above filters");
